 addLayer(){return this}
 setPaintProperty(){this.render();return this}
 setTerrain(t){this.terrainOn=Boolean(t);if(t)this.exaggeration=t.exaggeration;this.render();return this}
 resize(){this.w=this.el.clientWidth;this.h=this.el.clientHeight;const dpr=Math.min(devicePixelRatio||1,1.35);this.canvas.width=Math.round(this.w*dpr);this.canvas.height=Math.round(this.h*dpr);this.dpr=dpr}
 worldScale(){return 512*Math.pow(2,this.zoom)/C/Math.cos(this.center[1]*Math.PI/180)}
 async loadTerrain(){const generation=++this.generation;const z=clamp(Math.ceil(this.zoom),7,15);const n=2**z;const [cx,cy]=world(...this.center);const cols=6,rows=6,x0=Math.floor(cx*n)-3,y0=Math.floor(cy*n)-3,key=`${z}/${x0}/${y0}`;if(this.grid?.key===key)return;if(terrainCache.has(key)){this.grid=terrainCache.get(key);this.render();return}this.loading=true;const texture=document.createElement('canvas');texture.width=cols*TILE;texture.height=rows*TILE;const tc=texture.getContext('2d');tc.fillStyle='#203b28';tc.fillRect(0,0,texture.width,texture.height);const dem=document.createElement('canvas');dem.width=texture.width;dem.height=texture.height;const dc=dem.getContext('2d',{willReadFrequently:true});dc.fillStyle='rgb(128,0,0)';dc.fillRect(0,0,dem.width,dem.height);const grid={key,z,x0,y0,cols,rows,texture,dem:null};let imagery=0,elevation=0;const tasks=[];for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const tx=x0+x,ty=y0+y;tasks.push(async()=>{const im=await image(tileUrl('image',z,tx,ty));tc.drawImage(im,x*TILE,y*TILE,TILE,TILE);imagery++});tasks.push(async()=>{const im=await image(tileUrl('dem',z,tx,ty));dc.drawImage(im,x*TILE,y*TILE,TILE,TILE);elevation++})}await pool(tasks);if(generation!==this.generation)return;grid.dem=dc.getImageData(0,0,dem.width,dem.height).data;this.grid=grid;this.loading=false;if(imagery===0||elevation===0){this.emit('error',{error:new Error('Terrain tiles could not load')});return}terrainCache.set(key,grid);if(terrainCache.size>4)terrainCache.delete(terrainCache.keys().next().value);this.emit('sourcedata',{sourceId:'pnoa',sourceDataType:'content'});this.emit('sourcedata',{sourceId:'terrain',sourceDataType:'content'});this.render();}
 elevationAt(lng,lat){if(!this.grid?.dem)return 0;const g=this.grid,[wx,wy]=world(lng,lat),n=2**g.z;const u=Math.round((wx*n-g.x0)*TILE),v=Math.round((wy*n-g.y0)*TILE);if(u<0||u>=g.texture.width||v<0||v>=g.texture.height)return 0;const i=(v*g.texture.width+u)*4,d=g.dem;return d[i]*256+d[i+1]+d[i+2]/256-32768}
 project(p){const [wx,wy]=world(p[0],p[1]),[cx,cy]=world(...this.center);const meters=C*Math.cos(this.center[1]*Math.PI/180);const x=(wx-cx)*meters,y=(cy-wy)*meters,z=(this.terrainOn?this.elevationAt(p[0],p[1])*this.exaggeration:0)-this.base;return this.projectXYZ(x,y,z)}
 projectXYZ(x,y,z){const b=this.bearing*Math.PI/180,a=this.pitch*Math.PI/180,cb=Math.cos(b),sb=Math.sin(b),ca=Math.cos(a),sa=Math.sin(a);const xr=x*cb-y*sb,yr=x*sb+y*cb;const focal=Math.max(this.h,500)*1.25,dist=focal/this.worldScale();const depth=dist+yr*sa-z*ca;const p=this.padding;const sx=(this.w+p.left-p.right)/2,sy=(this.h+p.top-p.bottom)/2;return {x:sx+xr*focal/depth,y:sy-(yr*ca+z*sa)*focal/depth,depth}}
 unproject(x,y){const p=this.padding,sx=(this.w+p.left-p.right)/2,sy=(this.h+p.top-p.bottom)/2;const scale=this.worldScale(),focal=Math.max(this.h,500)*1.25,dist=focal/scale;const a=this.pitch*Math.PI/180,b=this.bearing*Math.PI/180;const q=-(y-sy)/focal;const yr=q*dist/(Math.cos(a)-q*Math.sin(a));const xr=(x-sx)*(dist+yr*Math.sin(a))/focal;const xx=xr*Math.cos(b)+yr*Math.sin(b),yy=-xr*Math.sin(b)+yr*Math.cos(b);const [cx,cy]=world(...this.center),meters=C*Math.cos(this.center[1]*Math.PI/180);const result=ll(cx+xx/meters,cy-yy/meters);for(let i=0;i<7;i++){const p0=this.project(result),epsilon=.00001,px=this.project([result[0]+epsilon,result[1]]),py=this.project([result[0],result[1]+epsilon]);const ax=(px.x-p0.x)/epsilon,ay=(px.y-p0.y)/epsilon,bx=(py.x-p0.x)/epsilon,by=(py.y-p0.y)/epsilon,det=ax*by-ay*bx;if(Math.abs(det)<1e-8)break;const ex=x-p0.x,ey=y-p0.y;if(Math.abs(ex)+Math.abs(ey)<.5)break;result[0]+=(ex*by-ey*bx)/det;result[1]+=(ey*ax-ex*ay)/det;}return {lng:result[0],lat:result[1]}}
 jumpTo(opts={}){if(opts.center)this.center=Array.isArray(opts.center)?opts.center:[opts.center.lng,opts.center.lat];if(opts.zoom!==undefined)this.zoom=clamp(opts.zoom,5,16);if(opts.pitch!==undefined)this.pitch=clamp(opts.pitch,0,74);if(opts.bearing!==undefined)this.bearing=opts.bearing;if(opts.padding!==undefined)this.padding=typeof opts.padding==='number'?{top:opts.padding,right:opts.padding,bottom:opts.padding,left:opts.padding}:{...this.padding,...opts.padding};this.render();this.emit('move',{});return this}
 easeTo(opts={}){this.jumpTo(opts);this.scheduleLoad();return this}
 flyTo(opts={}){return this.easeTo(opts)}
 fitBounds(bounds,opts={}){const sw=bounds.getSouthWest(),ne=bounds.getNorthEast();const center=[(sw.lng+ne.lng)/2,(sw.lat+ne.lat)/2];const span=Math.max(Math.abs(ne.lng-sw.lng)*Math.cos(center[1]*Math.PI/180),Math.abs(ne.lat-sw.lat)*1.6,.006);let available=this.w-((opts.padding?.left||0)+(opts.padding?.right||0));available=Math.max(260,available);const zoom=clamp(Math.log2(available*360/(512*span))-1,6,opts.maxZoom||15);return this.easeTo({...opts,center,zoom})}
 zoomIn(){this.zoom=clamp(this.zoom+.65,5,16);this.render();this.emit('zoomend');this.scheduleLoad()}
